-- AlterTable: بيانات البائع لفواتير ZATCA (المرحلة الأولى)
ALTER TABLE "PlatformSettings" ADD COLUMN     "sellerAddress" TEXT,
ADD COLUMN     "sellerLegalName" TEXT NOT NULL DEFAULT 'DMS — Digital Messaging System',
ADD COLUMN     "sellerVatNumber" TEXT;

-- AlterTable: توسيع CMS ليشمل /about و/services — القيم الافتراضية مطابقة للمحتوى الحالي المكتوب
-- مباشرة في الكود، بحيث لا يفقد الموقع أي محتوى فعلي عند أول انتقال لإدارته عبر admin/content.
ALTER TABLE "SiteContent" ADD COLUMN     "aboutHeading" TEXT NOT NULL DEFAULT 'من نحن',
ADD COLUMN     "aboutParagraphs" JSONB NOT NULL DEFAULT '["بدأت فكرة \"DMS\" (Digital Messaging System) من ملاحظة بسيطة تتكرر عند كل صاحب متجر وعيادة وصالون تقريباً: عملاؤك يراسلونك على واتساب، لكن رسائلهم موزّعة بين هاتف شخصي، وأحياناً أكثر من موظف، بلا أي سجل موحّد أو طريقة لمعرفة من ردّ على ماذا. النتيجة رسائل تُفقد، عملاء يُنتظَرون بلا رد، وفرص بيع حقيقية تضيع بصمت.","في المقابل، أغلب أدوات إدارة علاقات العملاء (CRM) العالمية إما لا تتحدث العربية بشكل طبيعي، أو لا تدعم واتساب كقناة تواصل أساسية أصلاً، أو معقدة أكثر مما يحتاجه صاحب نشاط صغير أو متوسط يريد فقط أن يرد على عملائه بسرعة ومنظّم.","بنينا DMS لتكون الحل العربي المباشر لهذه المشكلة: منصة واحدة تجمع محادثاتك، تؤتمت ردودك المتكررة عبر شات بوت ذكي، وتربط متجرك الإلكتروني مباشرة بواتسابك — كل ذلك عبر ربط رسمي مع WhatsApp Business Platform، وليس أدوات غير رسمية تعرّض رقمك للحظر.","فريقنا يجمع بين خبرة تقنية عميقة في بناء منصات SaaS، وفهم عملي لاحتياجات التجار العرب اليومية — لأننا بنينا هذه المنصة معتمدين على محادثات حقيقية مع أصحاب أنشطة تعاملوا مع نفس المشكلة كل يوم."]',
ADD COLUMN     "servicesHeading" TEXT NOT NULL DEFAULT 'خدماتنا',
ADD COLUMN     "servicesItems" JSONB NOT NULL DEFAULT '[{"title":"الحملات الإعلانية عبر واتساب","body":"أرسل حملات مجزّأة حسب شرائح عملائك (جدد، عملاء متكررون، سلة متروكة) باستخدام قوالب رسائل معتمدة من Meta. تتبّع نتائج كل حملة لحظياً: عدد المُرسَل، المُسلَّم، المقروء، والمبيعات الفعلية الناتجة عنها.","points":["استهداف بالشرائح والفلاتر","قوالب رسائل معتمدة رسمياً","تتبع تحويل المبيعات لكل حملة","حملات آلية (استرداد السلة المتروكة، تنشيط العملاء الخاملين)"]},{"title":"الشات بوت الذكي","body":"محرر تدفقات بصري بلا كود: صمّم رحلة الرد الآلي بالسحب والإفلات، اختبرها قبل النشر، وحوّل المحادثة لموظف بشري في أي لحظة تحتاج تدخلاً إنسانياً.","points":["محرر تدفقات بصري بلا كود","اختبار حي قبل النشر","تحويل سلس للموظف البشري","ردود سريعة محفوظة للأسئلة المتكررة"]},{"title":"CRM موحّد","body":"صندوق محادثات واحد يجمع كل رسائل عملائك عبر واتساب، مع ملف عميل كامل (بيانات، مرحلة الشراء، سجل الطلبات) وأدوات فريق (تعيين المحادثات، ملاحظات داخلية، أدوار وصلاحيات).","points":["صندوق محادثات موحّد للفريق كامل","ملف عميل كامل وسجل تفاعلات","تعيين المحادثات وملاحظات داخلية","أدوار وصلاحيات دقيقة لكل عضو"]},{"title":"تكامل المتاجر","body":"ربط حقيقي مع منصتي زد وسلة يزامن طلباتك ومنتجاتك تلقائياً، ويتيح حملات استرداد السلة المتروكة بلا أي تدخل يدوي.","points":["مزامنة تلقائية للطلبات والمنتجات","استرداد السلة المتروكة آلياً","ربط رقم واتساب Cloud API يدوياً أيضاً"]},{"title":"الربط الرسمي مع واتساب (Meta)","body":"المنصة مبنية على WhatsApp Business Platform الرسمي من Meta — ليست أداة غير رسمية تعرّض رقمك لخطر الحظر. هذا يعني موثوقية أعلى، إمكانية استخدام قوالب رسائل معتمدة، ودعماً لفريق أكبر على نفس الرقم.","points":["بناء على WhatsApp Business Platform الرسمي","لا خطر حظر الرقم كما في الأدوات غير الرسمية","قوالب رسائل معتمدة من Meta","دعم فريق متعدد على نفس رقم واتساب"]}]',
ADD COLUMN     "servicesSubheading" TEXT NOT NULL DEFAULT 'كل ما تحتاجه لإدارة تواصلك مع عملائك عبر واتساب، في منصة واحدة.';
